// Sammelfreigabe aus dem Cockpit (Beschluss Sales-Update 28.09.): Eine Freigabe trägt
// mehrere Entwürfe über mehrere Mandate. Das Vier-Augen-Prinzip bleibt (Human in the Loop,
// EU AI Act) – es sinkt nur der Klickaufwand.
// Erwartet: { entwuerfe: ["e1","e2", …], durchId, am? }  (einzelne Freigabe: ein Eintrag)
const b = $input.first().json.body ?? $input.first().json;
const ids = Array.isArray(b.entwuerfe) ? b.entwuerfe.filter(Boolean) : [b.entwurfId].filter(Boolean);
if (ids.length === 0) throw new Error('Freigabe ohne Entwürfe – Versand wird nicht gestartet');
if (!b.durchId) throw new Error('Freigabe ohne Person – Versand wird nicht gestartet');
const am = b.am ?? new Date().toISOString();
// Ein Item je Entwurf: WF 05 verarbeitet sie einzeln, der Audit-Eintrag bleibt je Entwurf nachvollziehbar.
return ids.map((entwurfId) => ({ json: { entwurfId, durchId: b.durchId, am, sammelfreigabe: ids.length > 1,
                                         anzahlInFreigabe: ids.length } }));

parameters.jsonBody:
={{ (() => {
const b = $json.body ?? $json;
const o = b.objekt ?? {};
const t = b.treffer ?? {};
const e = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const objektName = o.name || b.objektId || 'Objekt ohne Bezeichnung';
const link = (ents) => 'https://srv2104755.hstgr.cloud/webhook/seil/freigabe-link?entwurfId=' + encodeURIComponent(b.entwurfId ?? '')
  + '&objektId=' + encodeURIComponent(b.objektId ?? '')
  + '&durch=' + encodeURIComponent($json.freigabeAn ?? '')
  + '&entscheidung=' + ents;
const zeile = (k, v) => v ? '<tr><td style="padding:6px 14px 6px 0;color:#6b727b;font-size:13px;white-space:nowrap;vertical-align:top">' + k + '</td><td style="padding:6px 0;color:#16181c;font-size:13px">' + e(v) + '</td></tr>' : '';
const kriterium = (name, wert) => '<span style="display:inline-block;border:1px solid ' + (wert === true ? '#2f6b48' : wert === false ? '#9c4a42' : '#d6dade') + ';color:' + (wert === true ? '#2f6b48' : wert === false ? '#9c4a42' : '#6b727b') + ';border-radius:4px;padding:2px 8px;font-size:12px;margin-right:6px">' + name + ': ' + (wert === true ? 'passt' : wert === false ? 'passt nicht' : 'unbekannt') + '</span>';
const knopf = (text, href, haupt) => '<a href="' + href + '" style="display:inline-block;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:500;text-decoration:none;' + (haupt ? 'background:#41566e;color:#ffffff;border:1px solid #41566e' : 'background:#ffffff;color:#3b4149;border:1px solid #d6dade') + '">' + text + '</a>';

const html = '<!doctype html><html><body style="margin:0;padding:0;background:#f4f5f6">'
+ '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f6;padding:24px 12px"><tr><td align="center">'
+ '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#ffffff;border:1px solid #d6dade;border-radius:6px;font-family:Helvetica,Arial,sans-serif">'
+ '<tr><td style="padding:26px 28px 18px;border-bottom:1px solid #e4e7ea">'
+ '<div style="font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#6b727b">SEIL Real Estate &middot; Freigabe erforderlich</div>'
+ '<div style="font-size:21px;color:#16181c;margin-top:8px;line-height:1.3">' + e(objektName) + '</div>'
+ '<div style="font-size:14px;color:#3b4149;margin-top:8px">Ein Entwurf wartet auf Ihre Freigabe. Vor der Freigabe wird nichts versendet.</div>'
+ '</td></tr>'
+ '<tr><td style="padding:20px 28px 4px"><table role="presentation" cellpadding="0" cellspacing="0">'
+ zeile('Objekt', objektName)
+ zeile('Region', o.region)
+ zeile('Assetklasse', o.assetklasse)
+ zeile('Kaufpreis', o.kaufpreisMio ? o.kaufpreisMio + ' Mio. EUR' : '')
+ zeile('Investor', b.firma || b.investorId)
+ zeile('Ansprechpartner', b.ansprechpartner)
+ zeile('Empf&auml;nger', b.email)
+ '</table></td></tr>'
+ '<tr><td style="padding:14px 28px 0">'
+ '<div style="font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#6b727b;margin-bottom:8px">Abgleich</div>'
+ kriterium('Standort', t.standort) + kriterium('Assetklasse', t.assetklasse) + kriterium('Ticket', t.ticket)
+ '</td></tr>'
+ '<tr><td style="padding:20px 28px 0">'
+ '<div style="font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#6b727b;margin-bottom:8px">Entwurf</div>'
+ '<div style="border:1px solid #d6dade;border-radius:6px;background:#fbfbfc;padding:16px 18px;font-size:14px;line-height:1.6;color:#16181c;white-space:pre-wrap">' + e(b.entwurf) + '</div>'
+ '</td></tr>'
+ '<tr><td style="padding:22px 28px 6px">' + knopf('Freigeben und versenden', link('freigeben'), true)
+ '<span style="display:inline-block;width:10px"></span>' + knopf('Ablehnen', link('ablehnen'), false) + '</td></tr>'
+ '<tr><td style="padding:14px 28px 26px"><div style="font-size:12px;color:#6b727b;line-height:1.6">'
+ 'Ohne Entscheidung verf&auml;llt die Anfrage nach ' + e($json.fristTage) + ' Tagen. '
+ 'Der Entwurf wurde automatisch vorbereitet und ist bis zur Freigabe nicht versendet worden.'
+ '</div></td></tr>'
+ '</table></td></tr></table></body></html>';

return JSON.stringify({ message: {
  subject: 'Freigabe: ' + objektName + ' – Entwurf für ' + (b.firma || b.investorId || 'Investor'),
  body: { contentType: 'HTML', content: html },
  toRecipients: String($json.freigabeAn ?? '').split(/[;,]/).map(s => s.trim()).filter(Boolean).map(a => ({ emailAddress: { address: a } })),
}, saveToSentItems: true });
})() }}

