// Klick aus der Freigabe-Mail in die Form bringen, die die Sammelfreigabe erwartet.
const q = $input.first().json.query ?? {};
if (!q.entwurfId) throw new Error('Freigabe-Link ohne Entwurf');
if (q.entscheidung !== 'freigeben') {
  return [{ json: { abgelehnt: true, entwurfId: q.entwurfId,
                    antwort: 'Abgelehnt. Der Entwurf bleibt liegen, es wird nichts versendet.' } }];
}
return [{ json: { body: { entwuerfe: [q.entwurfId], objektId: q.objektId ?? null,
                          durchId: 'mail-link:' + (q.durch ?? 'unbekannt'),
                          am: new Date().toISOString() } } }];

parameters.jsonBody:
={{ JSON.stringify((() => {
const b = $json.body ?? $json;
const o = b.objekt ?? {};
const i = b.investor ?? {};
const t = b.treffer ?? {};
const marke = (n, w) => n + ': ' + (w === true ? 'passt' : w === false ? 'passt nicht' : 'unbekannt');
return {
  entwurf_id: String(b.entwurfId ?? ''),
  objekt: o.name || b.objektId || null,
  investor_firma: i.firma ?? null,
  investor_name: i.ansprechpartner ?? null,
  investor_email: i.email ?? null,
  betreff: b.betreff ?? null,
  entwurf: b.entwurf ?? b.text ?? null,
  treffer: [marke('Standort', t.standort), marke('Assetklasse', t.assetklasse), marke('Ticket', t.ticket)],
  status: 'offen'
};
})()) }}
